"""Everything a visitor reads is in the HTML itself, not generated by JavaScript."""
from playwright.sync_api import expect

from pages import Terminal

SECTIONS = ["ROOT VARIABLES", "TECH STACK", "WORK EXPERIENCE", "PROJECTS", "BLOG", "CONTACT"]


def test_raw_html_carries_the_whole_profile(doc):
    text = doc.body_text
    for expected in ["surya kulshreshtha", "PO-QA SDET / Test Automation Engineer", *SECTIONS, "passed"]:
        assert expected in text, f"{expected!r} missing from the served HTML"
    project_links = [a for a in doc.anchors if a["href"].startswith("https://github.com/suryakulshreshtha/")]
    assert len(project_links) >= 3


def test_works_with_javascript_switched_off(new_context, doc):
    page = new_context(java_script_enabled=False).new_page()
    term = Terminal(page).open(scripted=False)
    for i in range(term.blocks.count()):
        expect(term.blocks.nth(i)).to_be_visible()
    expect(term.skip_button).to_be_hidden()
    expect(term.links).to_have_count(len(doc.anchors))


def test_javascript_adds_nothing_crawlers_would_miss(page, new_context):
    animated = Terminal(page).finished().text()
    static_page = new_context(java_script_enabled=False).new_page()
    static = Terminal(static_page).open(scripted=False).text()
    assert animated == static


def test_heading_outline(page):
    Terminal(page).finished()
    expect(page.get_by_role("heading", level=1)).to_have_text("surya kulshreshtha")
    for name in SECTIONS:   # the ==== bars are aria-hidden, so names are just the titles
        expect(page.get_by_role("heading", level=2, name=name, exact=True)).to_have_count(1)
